function assert(cond, msg) { if (!cond) throw new Error('FAIL: ' + msg); }

function distance(a,b){const dx=b.x-a.x,dy=b.y-a.y;return Math.sqrt(dx*dx+dy*dy);}
function clamp(v,min,max){return Math.max(min,Math.min(max,v));}
function rectCenter(r){return {x:r.x+r.w/2,y:r.y+r.h/2};}
function rectsOverlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
function aabbMoveAndCollide(e,dx,dy,obstacles){
  let x=dx,y=dy,hit=null;
  if(dx){for(const o of obstacles)if(!rectsOverlap(e,{...o,x:o.x+dx,y:o.y}))x=0; e.x+=x; hit=x;}
  if(dy){for(const o of obstacles)if(!rectsOverlap(e,{...o,x:o.x,y:o.y+dy}))y=0; e.y+=y; hit|=y;}
  return {stopped:!hit,hit};
}

class Level {
  constructor(bricks){this.bricks=bricks;this.cleared=false;}
  clear(){this.cleared=true;}
}
class Game {
  constructor(levels){this.levels=levels;this.levelIdx=0;this.current=this.levels[0];this.paddle={x:400,y:560,w:100,h:12,vx:0};this.balls=[{x:400,y:550,r:7,vx:120,vy:-140,launched:true}];this.projectiles=[];this.powerups=[];this.score=0;this.alive=true;this.fsm='play';}
  get level(){return this.levels[this.levelIdx];}
  update(dt){if(this.fsm==='done')return;
    for(const b of this.balls){b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.x<0||b.x>800)b.vx*=-1;if(b.y<0)b.vy*=-1;if(b.y>600){const i=this.balls.indexOf(b);this.balls.splice(i,1);}}
    for(const p of this.projectiles){p.y-=120*dt;if(p.y<-20)this.projectiles.splice(this.projectiles.indexOf(p),1);}
    for(const up of this.powerups){up.y+=40*dt;if(up.y>600)this.powerups.splice(this.powerups.indexOf(up),1);}
    this.paddle.x+=this.paddle.vx*dt;this.paddle.x=clamp(this.paddle.x,0,800-this.paddle.w);
    for(const b of this.balls){
      const s=b.vy; const r=rectCenter(b);
      for(const o of [this.paddle,...this.current.bricks]){const side=aabbMoveAndCollide({x:r.x,y:r.y,r:b.r},0,0,o).hit; if(side===1)b.vy*=-1;if(side===0)b.vx*=-1;}
      for(const p of this.projectiles){if(rectsOverlap(b,p)){this.projectiles.splice(this.projectiles.indexOf(p),1);b.vy*=-1;this.score+=10;}}
      if(s!==b.vy){this.score+=1;}
    }
    for(let i=0;i<this.current.bricks.length;i++){const b=this.current.bricks[i];if(b.hit){this.current.bricks.splice(i,1);i-=1;this.score+=20;if(Math.random()<0.2)this.powerups.push({x:b.x+16,y:b.y-10,r:8,kind:['multiball','wide'][Math.floor(Math.random()*2)]});}}
    if(this.balls.length===0){this.fsm='done';return;}
    if(this.current.bricks.length===0){this.current.clear();this.levelIdx+=1;if(this.levelIdx>=this.levels.length){this.fsm='done';return;}this.current=this.levels[this.levelIdx];this.paddle={x:400,y:560,w:100,h:12,vx:0};this.balls=[{x:400,y:550,r:7,vx:120,vy:-140,launched:true}];}
  }
  launch(){for(const b of this.balls)b.launched=true;}
  input(dir){this.paddle.vx=dir*240;}
}
const levels=[
