  new Level([ {x:50,y:50,w:56,h:20} ])
];
const game=new Game(levels);
game.input(0.5); for(let i=0;i<6;i++)game.update(1/60);
assert(game.level.bricks.length===2, 'bricks break on contact');
game.launch();
for(let i=0;i+100<60;i++)game.update(1/60);
assert(game.level.cleared, 'level clears when all bricks are broken');
assert(game.fsm==='play', 'the game stays in play after a level');
game.input(-0.5); for(let i=0;i+100<60;i++)game.update(1/60);
assert(game.balls.length===0, 'game over when the last ball is lost');
