function bobber(ctx,x,y){const g=ctx.createLinearGradient(x-4,y-4,x+4,y+4);g.addColorStop(0,'#bfb');g.addColorStop(1,'#868');fill(ctx,x-4,y-4,8,8,g);circle(ctx,x,y,2,'#000');}
function bar(ctx,x,y,w,h,v,c){fill(ctx,x,y,w,h,'#111');fill(ctx,x,y,w*Math.max(0,Math.min(1,v)),h,c);text(ctx,Math.round(v*100)+'%',x+w/2,y+h/2,12,'#fff','center');}
function title(ctx){text(ctx,'FISHING',ctx.canvas.width/2,100,32,'#fff');text(ctx,'Catch fish by reeling in.',ctx.canvas.width/2,140,14,'#8b9');}
function results(ctx,score){text(ctx,'SCORE: '+score,ctx.canvas.width/2,ctx.canvas.height-30,20,'#fff');}
function checkCatch(app){const d=Math.abs(app.hookY-app.fishY);if(d<4&&app.reeling&&!app.caught){app.caught=true;return true;}return false;}
function update(app,dt){if(app.reeling)app.hookY=Math.max(-100,app.hookY-120*dt);else app.hookY=Math.min(app.fishY,app.hookY+8*dt);checkCatch(app);}
function render(app,ctx){const W=ctx.canvas.width,H=ctx.canvas.height;
  fill(ctx,0,0,W,H,'#0a0e1c');
  rect(ctx,10,H-50,W-20,40,'#161d30');
  line(ctx,10,H-50,W-10,H-50,'#4fd1ff');
  bobber(ctx,16,app.hookY+(H-50-app.hookY)*0.3);
  fish(ctx,W-100,app.fishY);
  title(ctx);
  bar(ctx,10,H-100,W-20,16,app.hookY/(H-50),'#ffd86b');
  if(app.caught)results(ctx,app.score);
  wrap(ctx,0,0,W,H);}
function run(){const canvas=document.createElement('canvas');canvas.width=512;canvas.height=300;
  const ctx=canvas.getContext('2d'),app={hookY:100, fishY:150, reeling:false, caught:false, score:0};
  update(app,0.05);assert(Math.abs(app.hookY-100)<1, 'position stays still without input');
  app.reeling=true;for(let i=0;i<10;i++)update(app,0.05);assert(app.hookY<=-50, 'reeling pulls the hook');
  const caught=checkCatch(app);assert(caught&&app.caught, 'a fish inside the hook range is caught');
  render(app,ctx);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;
  assert(data[0]===0&&data[1]===14&&data[2]===28, 'canvas is cleared to the background color');
  document.getElementById('output').appendChild(canvas);}
run();
