class Inventory {
  constructor(cap){this.slots=new Map();this.capacity=cap;this.carried=0;}
  add(item,q=1){if(this.carried+q>this.capacity)return false;this.carried+=q;const e=this.slots.get(item.id);if(e)e.qty+=q;else this.slots.set(item.id,{item,qty:q});return true;}
  remove(id,q=1){const e=this.slots.get(id);if(!e||e.qty<q)return null;e.qty-=q;if(e.qty===0)this.slots.delete(id);this.carried-=q;return e.item;}
  has(id){return this.slots.has(id);}
}
class Equipment {
  constructor(inv){this.inv=inv;this.worn=new Set();}
  equip(id){const item=this.inv.remove(id,1);if(!item)return false;for(const k of this.worn)this.inv.add(this.inv.slots.get(k).item,1);this.worn=new Set([id]);return true;}
  unequip(id){if(!this.worn.has(id))return false;this.worn.clear();this.inv.add(this.inv.slots.get(id).item,1);return true;}
  bonus(stat){let t=0;for(const id of this.worn){const item=this.inv.slots.get(id).item;if(item.mods&&item.mods[stat])t+=item.mods[stat];}return t;}
}
const inv=new Inventory(100);
const eq=new Equipment(inv);
