function clamp(min, max, value) {
  if (value < min) return min;
  if (value > max) return max;
  return value;
}

class Personality {
  constructor() {
    this.stats = { open: 0, conscientious: 0, agreeable: 0, neurotic: 0, introverted: 0 };
  }

  set(stat, value) {
    this.stats[stat] = clamp(0, 100, value);
  }

  get(stat) {
    return this.stats[stat] ?? 0;
  }

  average() {
    const total = Object.values(this.stats).reduce((sum, v) => sum + v, 0);
    return Math.round(total / Object.keys(this.stats).length);
  }
}{ Personality };
